with completed_orders as (
    select order_id
    from {{ ref('orders') }}
    where status = 'completed'
),

item_totals as (
    select order_id, sum(quantity * unit_price_cents)::bigint as gross_cents
    from {{ ref('order_items') }}
    group by order_id
),

payment_totals as (
    select order_id, sum(amount_cents)::bigint as paid_cents
    from {{ ref('payments') }}
    group by order_id
)

select o.order_id,
       coalesce(i.gross_cents, 0)::bigint as gross_cents,
       coalesce(p.paid_cents, 0)::bigint as paid_cents
from completed_orders o
left join item_totals i on o.order_id = i.order_id
left join payment_totals p on o.order_id = p.order_id

