select c.person_id, count(*) filter (where o.status='completed') completed_orders, sum(oi.quantity*oi.unit_price_cents) filter (where o.status='completed') gross
from main.orders o join main.customers c using(customer_id) left join main.order_items oi using(order_id)
group by 1 order by 1

select c.person_id, sum(r.paid_cents) refunds
from main.orders o join main.customers c using(customer_id) join main.refunds r using(order_id)
where o.status='completed' group by 1 order by 1

