select count(*) as mismatches from main.order_state s full outer join (
 select order_id, status, net_cents from (select *, row_number() over(partition by order_id order by updated_at desc, event_id desc) rn from main.order_events) where rn=1
) r using (order_id) where s.status is distinct from r.status or s.net_cents is distinct from r.net_cents or s.order_id is null or r.order_id is null

